import { Avatar } from '@refy-design/web';
export function Example() {
  return (
    <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
      {[
        'Example team',
        'Aurora team',
        'Origin team',
        'João Mendes',
        'Marina Salgado',
      ].map((name) => (
        <Avatar
          key={name}
          shape="square"
          size="lg"
          seed={name}
          initials={name
            .split(' ')
            .map((p) => p[0])
            .slice(0, 2)
            .join('')}
          title={name}
        />
      ))}
    </div>
  );
}

